fn is_nested(string: str) -> bool:
    """
    Create a function that takes a string as input which contains only square brackets.
    The function should return True if and only if there is a valid subsequence of brackets 
    where at least one bracket in the subsequence is nested.
    """
    var stack: [int] = []
    var pairs: [(int, int)] = []

    for i, char in enumerate(string):
        if char == '[':
            stack.append(i)
        elif char == ']':
            open_idx_opt = stack.pop()
            if open_idx_opt is not None:
                pairs.append((open_idx_opt, i))

    # Check for nesting: if pair (a, b) contains pair (c, d), then a < c and d < b
    for pair1 in pairs:
        for pair2 in pairs:
            if pair1 != pair2:
                a, b = pair1
                c, d = pair2
                if a < c and d < b:
                    return True

    return False

def is_nested(string: str) -> bool:
    """
    Create a function that takes a string as input which contains only square brackets.
    The function should return True if and only if there is a valid subsequence of brackets 
    where at least one bracket in the subsequence is nested.
    """
    # Identify which brackets form matched pairs
    stack: list[int] = []
    matched: list[bool] = [False] * len(string)

    for i, char in enumerate(string):
        if char == '[':
            stack.append(i)
        elif char == ']' and stack:
            j = stack.pop()
            matched[j] = True
            matched[i] = True

    # Check if the matched brackets contain nesting (depth >= 2)
    depth = 0
    for i, char in enumerate(string):
        if matched[i]:
            if char == '[':
                depth += 1
                if depth >= 2:
                    return True
            elif char == ']':
                depth -= 1

    return False

fn encode(message: str) -> str:
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    var result = ""
    for char in message:
        if char == " ":
            result += " "
        elif char == "a":
            result += "C"
        elif char == "e":
            result += "G"
        elif char == "i":
            result += "K"
        elif char == "o":
            result += "Q"
        elif char == "u":
            result += "W"
        elif char == "A":
            result += "c"
        elif char == "E":
            result += "g"
        elif char == "I":
            result += "k"
        elif char == "O":
            result += "q"
        elif char == "U":
            result += "w"
        elif char.isupper():
            result += char.lower()
        else:
            result += char.upper()
    return result

