fn lcs_of_three(X: str, Y: str, Z: str) -> int:
    """
    Write a function to find the longest common subsequence for the given three string sequence. https://www.geeksforgeeks.org/lcs-longest-common-subsequence-three-strings/
    """
    m = len(X)
    n = len(Y)
    o = len(Z)

    # Create a 3D DP table, initialized to 0
    var dp: [[[int]]] = []
    for i in range(m + 1):
        var layer_i: [[int]] = []
        for j in range(n + 1):
            var layer_j: [int] = []
            for k in range(o + 1):
                layer_j.append(0)
            layer_i.append(layer_j)
        dp.append(layer_i)

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            for k in range(1, o + 1):
                if X[i - 1] == Y[j - 1] and Y[j - 1] == Z[k - 1]:
                    dp[i][j][k] = dp[i - 1][j - 1][k - 1] + 1
                else:
                    dp[i][j][k] = max(dp[i - 1][j][k], dp[i][j - 1][k], dp[i][j][k - 1])

    return dp[m][n][o]

def lcs_of_three(X: str, Y: str, Z: str) -> int:
    """
    Write a function to find the longest common subsequence for the given three string sequence.
    """
    m = len(X)
    n = len(Y)
    p = len(Z)

    # Create a 3D DP table
    dp = [[[0 for _ in range(p + 1)] for _ in range(n + 1)] for _ in range(m + 1)]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            for k in range(1, p + 1):
                if X[i - 1] == Y[j - 1] == Z[k - 1]:
                    dp[i][j][k] = 1 + dp[i - 1][j - 1][k - 1]
                else:
                    dp[i][j][k] = max(dp[i - 1][j][k], dp[i][j - 1][k], dp[i][j][k - 1])

    return dp[m][n][p]

