def sumofFactors(n: int) -> int:
    """
    Write a function to find the sum of even factors of a number.
    """
    even_sum = 0
    i = 1

    while i * i <= n:
        if n % i == 0:
            if i % 2 == 0:
                even_sum += i
            if i != n // i and (n // i) % 2 == 0:
                even_sum += n // i
        i += 1

