fn power_base_sum(base: int, power: int) -> int:
    """
    Write a function that takes base and power as arguments and calculate the sum of all digits of the base to the specified power.
    """
    if power == 0:
        return 1

    abs_base = abs(base)
    var digits = digits_of(abs_base)

    for _ in range(power - 1):
        digits = multiply_digits(digits, abs_base)

    return sum(digits)

fn digits_of(n: int) -> [int]:
    """Convert a number to a list of digits."""
    if n == 0:
        return [0]
    var result: [int] = []
    var temp = n
    while temp > 0:
        result.insert(0, temp % 10)
        temp = temp // 10
    return result

fn multiply_digits(digits: [int], multiplier: int) -> [int]:
    """Multiply a number represented as digits by a multiplier."""
    if multiplier == 0:
        return [0]

    var result: [int] = []
    var carry = 0

    var i = len(digits) - 1
    while i >= 0:
        product = digits[i] * multiplier + carry
        result.insert(0, product % 10)
        carry = product // 10
        i -= 1

    while carry > 0:
        result.insert(0, carry % 10)
        carry = carry // 10

    return result

