fn max_sum(arr: [int]) -> int:
    """
    Write a function that takes an array and finds the maximum sum of a bitonic subsequence for the given array, where a sequence is bitonic if it is first increasing and then decreasing.
    """
    if len(arr) == 0:
        return 0

    n = len(arr)

    # Build inc array: inc[i] = maximum sum of increasing subsequence ending at index i
    var inc: [int] = []
    for i in range(n):
        var max_sum_here = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                max_sum_here = max(max_sum_here, inc[j] + arr[i])
        inc.append(max_sum_here)

    # Build dec array: dec[i] = maximum sum of decreasing subsequence starting at index i
    var dec: [int] = []
    for _ in range(n):
        dec.append(0)

    dec[n - 1] = arr[n - 1]
    for i in range(n - 2, -1, -1):
        var max_sum_here = arr[i]
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                max_sum_here = max(max_sum_here, dec[j] + arr[i])
        dec[i] = max_sum_here

    # Find maximum bitonic sum
    var result = 0
    for i in range(n):
        result = max(result, inc[i] + dec[i] - arr[i])

    return result

def max_sum(arr: list[int]) -> int:
    """
    Write a function that takes an array and finds the maximum sum of a bitonic subsequence for the given array, where a sequence is bitonic if it is first increasing and then decreasing.
    """
    if not arr:
        return 0

    n = len(arr)

    # inc[i] = maximum sum of increasing subsequence ending at i
    inc = [0] * n
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # dec[i] = maximum sum of decreasing subsequence starting at i
    dec = [0] * n
    for i in range(n - 1, -1, -1):
        dec[i] = arr[i]
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # Find maximum bitonic sum
    # A bitonic subsequence with peak at i has sum: inc[i] + dec[i] - arr[i]
    # (subtract arr[i] once since it's counted in both inc and dec)
    max_bitonic = inc[0] + dec[0] - arr[0]
    for i in range(1, n):
        max_bitonic = max(max_bitonic, inc[i] + dec[i] - arr[i])

    return max_bitonic

