def get_max_sum(n: int) -> int:
    """
    Write a function to find the maximum sum possible by using the given equation f(n) = max( (f(n/2) + f(n/3) + f(n/4) + f(n/5)), n).
    """
    memo: dict[int, int] = {}

    def f(x: int) -> int:
        if x == 0:
            return 0
        if x == 1:
            return 1

        if x in memo:
            return memo[x]

        # Calculate f(x/2) + f(x/3) + f(x/4) + f(x/5)
        sum_divisions = f(x // 2) + f(x // 3) + f(x // 4) + f(x // 5)

        # Return the maximum of either x or the sum
        result = max(sum_divisions, x)
        memo[x] = result
        return result

    return f(n)

