fn last_Digit_Factorial(n: int) -> int:
    """
    Write a function to find the last digit in factorial of a given number.
    """
    if n >= 5:
        return 0

    var factorial = 1
    for i in range(1, n + 1):
        factorial *= i

    return factorial % 10

fn comb_sort(nums: [int]) -> [int]:
    """
    Write a function to sort a list of elements.
    """
    var result = nums
    var gap = len(result)
    var shrink = 1.3

    while True:
        gap = int(float(gap) / shrink)
        if gap < 1:
            gap = 1

        var swapped = False
        var i = 0

        while i + gap < len(result):
            if result[i] > result[i + gap]:
                var temp = result[i]
                result[i] = result[i + gap]
                result[i + gap] = temp
                swapped = True
            i += 1

        if gap == 1 and not swapped:
            break

    return result

