fn two_unique_nums(nums: [int]) -> [int]:
    """
    Write a function to remove duplicate numbers from a given number of lists.
    """
    var seen: {int} = set()
    var result: [int] = []
    for n in nums:
        if n not in seen:
            seen.add(n)
            result.append(n)
    return result

fn two_unique_nums(nums: [int]) -> [int]:
    """
    Write a function to remove duplicate numbers from a given number of lists.
    """
    var count: {int: int} = {}
    for n in nums:
        count[n] = count.get(n, 0) + 1

    var result: [int] = []
    var seen: {int} = set()
    for n in nums:
        if count[n] == 1 and n not in seen:
            result.append(n)
            seen.add(n)
    return result

