fn max_aggregate(stdata: [(str, int)]) -> (str, int):
    """
    Write a function to calculate the maximum aggregate from the list of tuples.
    """
    var aggregate: {str: int} = {}

    for s, count in stdata:
        if s in aggregate:
            aggregate[s] += count
        else:
            aggregate[s] = count

    var max_key = ""
    var max_value = 0

    for key, value in aggregate.items():
        if value > max_value:
            max_key = key
            max_value = value

    return (max_key, max_value)

def max_aggregate(stdata: list[tuple[str, int]]) -> tuple[str, int]:
    """
    Write a function to calculate the maximum aggregate from the list of tuples.
    """
    if not stdata:
        return ("", 0)

    aggregates: dict[str, int] = {}
    for key, value in stdata:
        aggregates[key] = aggregates.get(key, 0) + value

    return max(aggregates.items(), key=lambda x: x[1])

