fn snake_to_camel(word: str) -> str:
    """
    Write a function to convert the given snake case string to camel case string.
    """
    parts = word.split("_")

    if len(parts) == 0:
        return ""

    var result = parts[0].lower()

    for i in range(1, len(parts)):
        part = parts[i]
        if len(part) > 0:
            result = result + part[0].upper() + part[1:]

    return result

