def last(arr: list[int], x: int) -> int:
    """
    Write a function to find the last position of an element in a sorted array.
    """
    left, right = 0, len(arr) - 1
    result = -1

    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            result = mid
            left = mid + 1  # Continue searching in the right half
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    return result

