fn decimal_to_binary(n: int) -> str:
    """
    Write a function to convert the given decimal number to its binary equivalent, represented as a string with no leading zeros.
    """
    if n == 0:
        return "0"

    var is_negative = n < 0
    var num = abs(n)
    var result: [str] = []

    while num > 0:
        remainder = num % 2
        result.append(str(remainder))
        num = num // 2

    result.reverse()
    var binary_str = "".join(result)

    if is_negative:
        return "-" + binary_str
    return binary_str

def decimal_to_binary(n: int) -> str:
    """
    Write a function to convert the given decimal number to its binary equivalent, represented as a string with no leading zeros.
    """
    if n >= 0:
        return bin(n)[2:]
    else:
        return '-' + bin(n)[3:]

